question.brute_force_solution:
class Solution {
    public int longestSubarray(int[] nums, int limit) {
        int n = nums.length;
        int best = 0;
        for (int i = 0; i < n; i++) {
            int curMax = nums[i];
            int curMin = nums[i];
            for (int j = i; j < n; j++) {
                curMax = Math.max(curMax, nums[j]);
                curMin = Math.min(curMin, nums[j]);
                if (curMax - curMin <= limit) {
                    best = Math.max(best, j - i + 1);
                } else {
                    // further extension will only increase the range
                    break;
                }
            }
        }
        return best;
    }
}

question.optimal_solution:
import java.util.*;
class Solution {
    public int longestSubarray(int[] nums, int limit) {
        Deque<Integer> maxDeque = new ArrayDeque<>(); // stores indices, decreasing values
        Deque<Integer> minDeque = new ArrayDeque<>(); // stores indices, increasing values
        int left = 0, result = 0;
        for (int right = 0; right < nums.length; right++) {
            // maintain maxDeque
            while (!maxDeque.isEmpty() && nums[maxDeque.peekLast()] < nums[right]) {
                maxDeque.pollLast();
            }
            maxDeque.offerLast(right);
            // maintain minDeque
            while (!minDeque.isEmpty() && nums[minDeque.peekLast()] > nums[right]) {
                minDeque.pollLast();
            }
            minDeque.offerLast(right);
            // shrink window if condition violated
            while (nums[maxDeque.peekFirst()] - nums[minDeque.peekFirst()] > limit) {
                if (maxDeque.peekFirst() == left) maxDeque.pollFirst();
                if (minDeque.peekFirst() == left) minDeque.pollFirst();
                left++;
            }
            result = Math.max(result, right - left + 1);
        }
        return result;
    }
}
